  "claims": [
    {
      "id": "rc:3544794067",
      "kind": "correctness",
      "harm": "order-dependent addition in addMissingTxs could leave partially applied state if an invalid transaction aborts the loop early",
      "quote": "AddMissingTxs is order-dependent, a bad entry aborts the loop at that point, so [valid, invalid] keeps valid but [invalid, valid] doesn't. Is this intentional? Correct me if I am wrong but validate-then-apply seems to be a safer approach.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:5062080068"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5062080068",
      "settled_by_quote": "Addressed @ViniciusCestarii's inline comments https://github.com/bitcoin/bitcoin/pull/35671#pullrequestreview-4655098156. Ready for review."
    },
    {
      "id": "c:4974409738",
      "kind": "safety",
      "harm": "non-differential indices allow repeated requests for the same transaction, risking buffer overflow or out-of-memory errors",
      "quote": "compact blocks uses a differential index not primarily for efficiency... but so that the wire format is safe by construction against an attack that applies the same large transaction over and over again (e.g. if index 5 is some giant txn, you request 5,5,5,5,5,5...) and overflows a buffer or OOMs an implementation explicitly constructs the block and without having to have expensive duplication checks.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:4978780547"
      ],
      "fix_pushed": false,
      "settled_by_id": "c:4978780547",
      "settled_by_quote": "the Mining IPC client is expected to run on the same machine, so unknownTxPos() and addMissingTxs() are not designed for bandwidth efficiency. We also (currently) more or less trust the IPC client. It needs to deal with any hardening against its clients itself."
    },
    {
      "id": "rc:3768404613",
      "kind": "correctness",
      "harm": "addMissingTxs checks transaction count rather than weight, permitting oversized transaction payloads to be stored before block validation",
      "quote": "The check here is against the size, but it does not check the weight. So even though it can reject a million tiny transactions, it can accept 16666 large ones... This would be eventually rejected as oversized in makeTemplate when TestBlockValidity is called, but that is a bit too late.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3820690848"
      ],
      "fix_pushed": false,
      "settled_by_id": "rc:3820690848",
      "settled_by_quote": "I don't think we should take over too much work that TestBlockValidity() does for us. Duplicating consensus checks could introduce new bugs."
    }
  ],
